<template><section class="auth-shell"><div class="auth-card"><p class="eyebrow">Учебный доступ</p><h1>С возвращением</h1><p>Используйте демо-профиль или зарегистрируйте локальную учебную учётную запись.</p><form @submit.prevent="submit"><div v-if="error" class="alert alert-danger" role="alert">{{ error }}</div><label>E-mail<input v-model.trim="email" required type="email" autocomplete="email" /></label><label>Пароль<input v-model="password" required type="password" minlength="6" autocomplete="current-password" /></label><button class="btn btn-clay wide" :disabled="busy">{{ busy ? 'Входим…' : 'Войти в учебный профиль' }}</button></form><button class="btn btn-soft wide" @click="demo">Подставить демо-данные</button><p>Нет профиля? <RouterLink :to="{name:'register',query:$route.query}">Зарегистрироваться</RouterLink></p></div></section></template><script setup>import { ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { useSession } from '../composables/useSession'; const router=useRouter(),route=useRoute(); const {login}=useSession(); const email=ref(''),password=ref(''),error=ref(''),busy=ref(false); const demo=()=>{email.value='demo@tabletime.local';password.value='учебный-доступ';}; async function submit(){busy.value=true;error.value='';try{await login(email.value,password.value);const next=typeof route.query.next==='string' ? route.query.next : '/profile';router.replace(next);}catch(e){error.value=e.message;}finally{busy.value=false;}}</script>
